//! Authority for motion intents. Planning is not an applied acknowledgement.
use std::collections::{BTreeMap,BTreeSet};
use crate::core::{motion::MotionDocument,motion_protocol::{MotionPlaybackState,PlaybackStatus,PendingMotionCommand,MotionAppliedAck,MotionAckKind}};
#[derive(Debug,Clone)]
pub struct Step { pub id:Option<String>,pub start:f64,pub end:f64 }
#[derive(Debug,Clone)]
pub struct MotionSession {pub pages:BTreeMap<String,Vec<Step>>,pub background_pages:BTreeSet<String>,pub confirmed:Option<MotionPlaybackState>,pub planning:Option<u64>,pub control:Option<(String,Option<f64>)>,pub pending:Option<PendingMotionCommand>,pub pending_state:Option<MotionPlaybackState>,pub last_sequence:u64,pub last_calibration_sample:u64,pub queued:u32}
impl MotionSession {
 pub fn new(document:MotionDocument)->Self {let mut pages=BTreeMap::new();let mut background_pages=BTreeSet::new();for page in document.pages {if page.background.is_some(){background_pages.insert(page.id.clone());}let mut steps=vec![Step{id:None,start:0.0,end:0.0}];let mut previous=None::<(f64,f64)>;let mut total:f64=0.0;for action in page.actions {if action.trigger=="click"{steps.push(Step{id:Some(action.id),start:total,end:total});previous=None;}let step=steps.last_mut().unwrap();let anchor=match previous {Some((start,end))=>if action.trigger=="withPrevious"{start}else{end},None=>step.start};let start=anchor+action.delay_ms;let end=start+action.params["durationMs"];step.end=step.end.max(end);total=total.max(end);previous=Some((start,end));}pages.insert(page.id,steps);}Self{pages,background_pages,confirmed:None,planning:None,control:None,pending:None,pending_state:None,last_sequence:0,last_calibration_sample:0,queued:0}}
 pub fn valid(&self,state:&MotionPlaybackState)->bool {let Some(step)=self.pages.get(&state.page_id).and_then(|steps|steps.get(state.step_index as usize))else{return false;};state.valid()&&state.motion_revision==0&&state.step_id==step.id&&(self.background_pages.contains(&state.page_id)||state.background_time_ms==0.0)&&state.logical_time_ms>=step.start&&state.logical_time_ms<=step.end&&(state.playback_status!=PlaybackStatus::Finished||state.logical_time_ms==step.end)}
 pub fn begin(&mut self,sequence:u64)->bool {if sequence<=self.last_sequence||self.planning.is_some()||self.pending.is_some(){return false;}self.control=None;self.planning=Some(sequence);true}
 pub fn begin_control(&mut self,sequence:u64,action:&str,time:Option<f64>)->bool{if !["pause","resume","replay","seek"].contains(&action)||action=="seek"&&!time.is_some_and(|v|v.is_finite()&&v>=0.0&&self.confirmed.as_ref().and_then(|state|self.pages.get(&state.page_id)).and_then(|steps|steps.last()).is_some_and(|step|v<=step.end))||action!="seek"&&time.is_some()||!self.begin(sequence){return false;}self.control=Some((action.into(),time));true}
 pub fn plan(&mut self,id:&str,generation:u64,sequence:u64,state:&MotionPlaybackState)->bool {if self.planning!=Some(sequence)||!self.valid(state){return false;}let Some(old)=&self.confirmed else{return false;};if state.page_id!=old.page_id{return false;}if let Some((action,time))=&self.control{let same=state.step_index==old.step_index&&state.logical_time_ms>=old.logical_time_ms&&state.background_time_ms>=old.background_time_ms;let accepted=match action.as_str(){"pause"=>same&&state.playback_status==PlaybackStatus::Paused,"resume"=>same&&[PlaybackStatus::Playing,PlaybackStatus::Finished].contains(&state.playback_status),"replay"=>state.step_index==0&&state.logical_time_ms==0.0&&state.background_time_ms==0.0&&state.playback_status==PlaybackStatus::Playing,"seek"=>self.pages.get(&state.page_id).and_then(|steps|steps.iter().rposition(|step|step.start<=state.logical_time_ms)).is_some_and(|index|index==state.step_index as usize)&&time.is_some_and(|t|state.logical_time_ms==t&&state.background_time_ms==if self.background_pages.contains(&state.page_id){t}else{0.0})&&state.playback_status==PlaybackStatus::Paused,_=>false};if !accepted{return false;}}else if state.background_time_ms<old.background_time_ms||!(state.step_index==old.step_index&&state.playback_status==PlaybackStatus::Finished||state.step_index==old.step_index+1&&state.playback_status==PlaybackStatus::Playing){return false;}if let Some(pending)=&self.pending{return pending.sequence==sequence&&pending.step_index==state.step_index&&pending.step_id==state.step_id;}
 self.pending_state=Some(state.clone());self.pending=Some(PendingMotionCommand{session_id:id.into(),generation,sequence,page_id:state.page_id.clone(),step_id:state.step_id.clone(),step_index:state.step_index,motion_revision:state.motion_revision});true}
 pub fn acknowledge(&mut self,id:&str,generation:u64,sequence:u64,state:MotionPlaybackState)->bool {if !self.valid(&state)||self.pending_state.as_ref().is_some_and(|planned|state.background_time_ms<planned.background_time_ms||state.logical_time_ms<planned.logical_time_ms){return false;}let Some(pending)=&self.pending else{return false;};let ack=MotionAppliedAck{session_id:id.into(),generation,sequence,kind:MotionAckKind::Applied,state:state.clone()};if !pending.accepts(&ack,self.last_sequence){return false;}self.confirmed=Some(state);self.last_sequence=sequence;self.planning=None;self.control=None;self.pending=None;self.pending_state=None;true}
 pub fn request_page(&mut self,sequence:u64,state:MotionPlaybackState)->bool{if self.control.is_some()||self.planning!=Some(sequence)||self.pending.is_some()||!self.valid(&state)||state.playback_status!=PlaybackStatus::Finished||state.step_index!=self.count(&state.page_id)||!self.confirmed.as_ref().is_some_and(|old|old.page_id==state.page_id&&old.step_index==state.step_index&&state.background_time_ms>=old.background_time_ms){return false;}self.confirmed=Some(state);self.planning=None;self.pending_state=None;true}
 pub fn calibrate(&mut self,sequence:u64,state:MotionPlaybackState)->bool {if self.planning.is_some()||sequence!=self.last_sequence||!self.valid(&state){return false;}let Some(old)=&self.confirmed else{return false;};if state.page_id!=old.page_id||state.step_index!=old.step_index||state.logical_time_ms<old.logical_time_ms||state.background_time_ms<old.background_time_ms{return false;}self.confirmed=Some(state);true}
 pub fn calibrate_sample(&mut self,sequence:u64,sample:u64,state:MotionPlaybackState)->bool{if sample<=self.last_calibration_sample||!self.calibrate(sequence,state){return false;}self.last_calibration_sample=sample;true}
 pub fn ready(&mut self,state:MotionPlaybackState)->bool{if !self.valid(&state){return false;}self.confirmed=Some(state);self.last_calibration_sample=0;self.clear_pending();true}
 pub fn clear_pending(&mut self){self.planning=None;self.control=None;self.pending=None;self.pending_state=None;self.queued=0;}
 pub fn count(&self,page:&str)->u32{self.pages.get(page).map(|s|s.len().saturating_sub(1) as u32).unwrap_or(0)}
}
#[cfg(test)]mod tests {use super::*;fn session()->MotionSession{let mut document=crate::core::motion::validate(include_str!("../../../tests/fixtures/motion/valid.json")).unwrap();document.pages[0].actions[0].delay_ms=0.0;MotionSession::new(document)}fn state(s:&MotionSession,index:u32,status:PlaybackStatus)->MotionPlaybackState{let (page,steps)=s.pages.first_key_value().unwrap();let step=&steps[index as usize];MotionPlaybackState{page_id:page.clone(),step_id:step.id.clone(),step_index:index,playback_status:status.clone(),logical_time_ms:if status==PlaybackStatus::Finished{step.end}else{step.start},background_time_ms:0.0,motion_revision:0}}
#[test]fn plan_never_confirms_and_ack_is_exact(){let mut s=session();assert!(s.ready(state(&s,0,PlaybackStatus::Finished)));assert!(s.begin(1));let next=state(&s,1,PlaybackStatus::Playing);assert!(s.plan("s",3,1,&next));assert_eq!(s.confirmed.as_ref().unwrap().step_index,0);assert!(!s.acknowledge("s",2,1,next.clone()));assert!(!s.acknowledge("other",3,1,next.clone()));assert!(!s.acknowledge("s",3,2,next.clone()));assert!(s.acknowledge("s",3,1,next.clone()));assert!(!s.acknowledge("s",3,1,next));}
#[test]fn stale_calibration_and_cross_page_are_rejected(){let mut s=session();assert!(s.ready(state(&s,1,PlaybackStatus::Playing)));let end=state(&s,1,PlaybackStatus::Finished);assert!(s.calibrate(0,end));assert!(!s.calibrate(0,state(&s,1,PlaybackStatus::Playing)));assert!(!s.calibrate(1,state(&s,1,PlaybackStatus::Finished)));let mut bad=state(&s,1,PlaybackStatus::Finished);bad.motion_revision=1;assert!(!s.valid(&bad));}
#[test]fn background_time_is_monotonic_and_source_bound(){let mut s=session();let mut initial=state(&s,0,PlaybackStatus::Finished);initial.background_time_ms=100.0;assert!(!s.valid(&initial));s.background_pages.insert(initial.page_id.clone());assert!(s.ready(initial.clone()));initial.background_time_ms=250.0;assert!(s.calibrate(0,initial.clone()));initial.background_time_ms=249.0;assert!(!s.calibrate(0,initial));assert!(s.begin(1));let mut next=state(&s,1,PlaybackStatus::Playing);next.background_time_ms=249.0;assert!(!s.plan("s",1,1,&next));next.background_time_ms=300.0;assert!(s.plan("s",1,1,&next));assert!(s.acknowledge("s",1,1,next));}

#[test]fn page_request_ends_planning_before_frozen_state_calibration(){let mut s=session();let end=state(&s,1,PlaybackStatus::Finished);assert!(s.ready(end.clone()));assert!(s.begin(1));let mut frozen=end.clone();frozen.playback_status=PlaybackStatus::Paused;assert!(!s.calibrate(0,frozen.clone()));assert!(s.request_page(1,end.clone()));assert!(!s.request_page(1,end));assert!(s.calibrate(0,frozen));assert!(s.planning.is_none());}

#[test]fn same_time_calibration_cannot_reorder_pause_and_resume(){let mut s=session();let mut playing=state(&s,1,PlaybackStatus::Playing);assert!(s.ready(playing.clone()));playing.playback_status=PlaybackStatus::Paused;assert!(s.calibrate_sample(0,2,playing.clone()));playing.playback_status=PlaybackStatus::Playing;assert!(!s.calibrate_sample(0,1,playing.clone()));assert!(!s.calibrate_sample(0,2,playing.clone()));assert!(s.calibrate_sample(0,3,playing));}

#[test]fn explicit_controls_can_seek_back_without_weakening_normal_advance(){let mut s=session();let mut live=state(&s,1,PlaybackStatus::Playing);live.logical_time_ms=500.0;assert!(s.ready(live.clone()));assert!(!s.begin_control(1,"seek",Some(f64::NAN)));assert!(!s.begin_control(1,"pause",Some(1.0)));assert!(!s.begin_control(1,"seek",Some(999999.0)));assert!(s.begin_control(1,"pause",None));let mut paused=live.clone();paused.logical_time_ms=600.0;paused.playback_status=PlaybackStatus::Paused;assert!(s.plan("s",1,1,&paused));assert_eq!(s.confirmed.as_ref().unwrap().logical_time_ms,500.0);assert!(s.acknowledge("s",1,1,paused));assert!(s.begin_control(2,"seek",Some(100.0)));let mut sought=live.clone();sought.logical_time_ms=100.0;sought.playback_status=PlaybackStatus::Paused;assert!(s.plan("s",1,2,&sought));assert!(s.acknowledge("s",1,2,sought.clone()));assert!(!s.calibrate(1,live));assert!(s.begin_control(3,"replay",None));let start=state(&s,0,PlaybackStatus::Playing);assert!(s.plan("s",1,3,&start));assert!(s.acknowledge("s",1,3,start));assert!(s.control.is_none());}

}
